export type NutritionFacts = {
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
};

// Per-nutrient metadata. Adding a nutrient is one line on NutritionFacts +
// one entry here; everything else iterates this map. The two ceilings bound
// hand-entered food: pure fat is 9 cal/g by Atwater and pure oil is 1 g of fat
// per gram, so 10 and 1.1 leave room for label rounding and nothing more.
export const NUTRIENTS: Record<keyof NutritionFacts, {
  label: string;
  shortLabel: string;
  calPerGram: number;
  unit: 'cal' | 'g';
  decimals: number;
  sliceColor: string;
  maxPerServing: number;
  maxPerGram: number;
}> = {
  calories: { label: 'Calories', shortLabel: 'cal', calPerGram: 0, unit: 'cal', decimals: 0, sliceColor: 'var(--accent)', maxPerServing: 10000, maxPerGram: 10 },
  protein:  { label: 'Protein',  shortLabel: 'P',   calPerGram: 4, unit: 'g',   decimals: 1, sliceColor: 'var(--macro-protein)', maxPerServing: 1000, maxPerGram: 1.1 },
  carbs:    { label: 'Carbs',    shortLabel: 'C',   calPerGram: 4, unit: 'g',   decimals: 1, sliceColor: 'var(--macro-carbs)', maxPerServing: 1000, maxPerGram: 1.1 },
  fat:      { label: 'Fat',      shortLabel: 'F',   calPerGram: 9, unit: 'g',   decimals: 1, sliceColor: 'var(--macro-fat)', maxPerServing: 1000, maxPerGram: 1.1 },
};

export const NUTRIENT_KEYS = Object.keys(NUTRIENTS) as (keyof NutritionFacts)[];
export const MACRO_KEYS = NUTRIENT_KEYS.filter((k) => NUTRIENTS[k].calPerGram > 0);
export const CALORIE_KEYS = NUTRIENT_KEYS.filter((k) => NUTRIENTS[k].unit === 'cal');

export function nutrientCalories(key: keyof NutritionFacts, n: NutritionFacts): number {
  return CALORIE_KEYS.includes(key) ? n[key] : n[key] * NUTRIENTS[key].calPerGram;
}

export function macroPctOfCalories(n: NutritionFacts): Partial<Record<keyof NutritionFacts, number>> {
  if (!Number.isFinite(n.calories) || n.calories <= 0) {
    return {};
  }

  const out: Partial<Record<keyof NutritionFacts, number>> = {};
  for (const key of MACRO_KEYS) {
    out[key] = nutrientCalories(key, n) / n.calories * 100;
  }
  return out;
}

export type MacroShare = { key: keyof NutritionFacts; value: number };

export function macroShares(n: NutritionFacts): MacroShare[] {
  const pcts = macroPctOfCalories(n);
  return MACRO_KEYS.map((key) => ({ key, value: pcts[key] ?? 0 }));
}

// The share of the macro calories, not of the stated calorie line: the two
// differ whenever a label's calories are rounded or padded by other nutrients.
// Shares print as whole numbers, so the remainder goes to the macros with the
// largest fractions — plain rounding would show 99% or 101% across the three.
export function macroSharePct(n: NutritionFacts): Partial<Record<keyof NutritionFacts, number>> {
  const parts = MACRO_KEYS.map((key) => ({ key, calories: nutrientCalories(key, n) }));
  const total = parts.reduce((sum, p) => sum + p.calories, 0);

  if (!Number.isFinite(total) || total <= 0) {
    return {};
  }

  const shares = parts.map(({ key, calories }) => {
    const exact = calories / total * 100;
    return { key, whole: Math.floor(exact), remainder: exact % 1 };
  });

  const short = 100 - shares.reduce((sum, s) => sum + s.whole, 0);
  const bumped = new Set([...shares].sort((a, b) => b.remainder - a.remainder).slice(0, short).map((s) => s.key));

  const out: Partial<Record<keyof NutritionFacts, number>> = {};
  for (const { key, whole } of shares) {
    out[key] = whole + (bumped.has(key) ? 1 : 0);
  }

  return out;
}

export type Unit = 'g' | 'oz' | 'lb' | 'count' | 'ml';

// A display-only unit for logging and recipe amounts — see DISPLAY_UNITS in units.ts.
export type DisplayUnitKey = 'fl oz';

// What the log and recipe pickers offer: a stored Unit, plus any display
// unit — see DISPLAY_UNITS in units.ts.
export type PickerUnit = Unit | DisplayUnitKey;

// What a user typed for an entry or portion whose stored amount/unit is
// physical, not what they entered (fl oz, or count on a food with pieces).
// Display and re-editing only — never used to compute nutrition.
export type Shown = { amount: number; unit: PickerUnit };

// How a meal header shows its macros: their share of macro calories, or grams.
export type MacroDisplay = 'percent' | 'grams';

export type Settings = {
  mealMacros: MacroDisplay;
};

export type Food = {
  id: string;
  name: string;
  brand?: string;
  nutritionFacts: NutritionFacts;
  servingSize: number;
  servingUnit: Unit;
  createdAt: string;
  deletedAt: string | null;
  source?: string;
  pieces?: Pieces;
};

export type Entry = {
  id: string;
  date: string;
  foodId: string;
  amount: number;
  unit: Unit;
  shown?: Shown;
  mealId: string;
  loggedAt: string;
  recipeLogId?: string;
};

export type Meal = {
  id: string;
  date: string;
  position: number;
};

// An amount of a food. `Entry` satisfies it structurally, so calc can sum a
// recipe's portions and a day's entries with one function.
export type Portion = {
  foodId: string;
  amount: number;
  unit: Unit;
  shown?: Shown;
};

// A Portion's amount/unit/shown, without which food it's of — what
// shownFor, resolvePickerAmount and the count migration all take or return.
export type AmountShown = Omit<Portion, 'foodId'>;

export type Recipe = {
  id: string;
  name: string;
  items: Portion[];
  createdAt: string;
  deletedAt: string | null;
};

// One logged instance of a recipe. The entries it produced carry this id via
// `recipeLogId` so the log view can group and delete them together while
// calc, export and the entry detail card keep treating them as plain entries.
export type RecipeLog = {
  id: string;
  recipeId: string;
  servings: number;
};

export type State = {
  version: 2;
  enabledSources: string[];
  foods: Food[];
  meals: Meal[];
  entries: Entry[];
  recipes: Recipe[];
  recipeLogs: RecipeLog[];
  settings: Settings;
};

// pieces is not just optional but three-state: absent leaves it untouched,
// null clears it, a value sets it — the food form always submits one of the
// three, since (unlike the other fields) "no pieces" has no blank-string form.
export type FoodUpdates = Partial<Pick<Food, 'name' | 'nutritionFacts' | 'servingSize' | 'servingUnit'>> & {
  pieces?: Pieces | null;
};

export type RecipeUpdates = Partial<Pick<Recipe, 'name' | 'items'>>;

// A draft can't declare a group id, any more than it can declare a meal id —
// the reducer alone stamps both when it resolves the entry into a meal.
export type EntryDraft = Omit<Entry, 'mealId' | 'recipeLogId'>;

export type Action =
  | { type: 'LogEntry'; entry: EntryDraft; newMealId: string }
  | { type: 'NewMeal'; mealId: string; date: string }
  | { type: 'DeleteEntry'; entryId: string }
  | { type: 'AddFood'; food: Food }
  | { type: 'EditFood'; foodId: string; updates: FoodUpdates }
  | { type: 'SoftDeleteFood'; foodId: string; deletedAt: string }
  | { type: 'ReviveFood'; food: Food }
  | { type: 'AddRecipe'; recipe: Recipe }
  | { type: 'EditRecipe'; recipeId: string; updates: RecipeUpdates }
  | { type: 'SoftDeleteRecipe'; recipeId: string; deletedAt: string }
  | { type: 'LogRecipe'; recipeLog: RecipeLog; entries: EntryDraft[]; newMealId: string }
  | { type: 'DeleteRecipeLog'; recipeLogId: string }
  | { type: 'ReplaceState'; state: State }
  | { type: 'SetSourceEnabled'; source: string; enabled: boolean }
  | { type: 'UpdateSettings'; updates: Partial<Settings> };

// One serving of a food is this many discrete pieces ("1 Bottle", "8
// cookies"): noun is a brand's own label word for one (kept verbatim,
// lower-cased, never pluralized or reworded) or, for a generic USDA row,
// the word the data build picked from its stated portion ("medium", "can").
// Only meaningful when servingUnit isn't already 'count' — a counted food
// has no separate piece size to record.
export type Pieces = { perServing: number; noun?: string };

// brand: the label a brand-partition row was built under. It rides along
// onto the Food that Add creates and is what the tag, the brand half of
// search and food identity read. Only loading a food saved from a store pack
// before rows carried a brand derives one from `source` (stampLegacyBrands).
export type SourcedFood = {
  id: string;
  name: string;
  brand?: string;
  nutritionFacts: NutritionFacts;
  servingSize: number;
  servingUnit: Unit;
  source: string;
  sourceId: string;
  tags?: string[];
  pieces?: Pieces;
};

export type SearchOptions = {
  limit?: number;
  sources?: string[];
};
